"""Writes docs/REPORT_FACTS.md from the experiment JSON files (single human-readable copy of every number used in the documents).

    python -m scripts.docs.make_report_facts
"""
import os

from . import facts as F

K = F.K()
R, H, W, L, A = F.REAL, F.HYB, F.WIN, F.LAT, F.API


def row(*c):
    return "| " + " | ".join(str(x) for x in c) + " |"


def m(d, keys=("accuracy", "precision", "recall", "f1", "fpr")):
    return [f"{d[k] * 100:.2f} %" for k in keys]


def build():
    o = []
    a = o.append
    a("# SentinelFlow (CSE-C-C15) - REPORT FACTS\n")
    a("Generated by `scripts/docs/make_report_facts.py` from `results/metrics.json` and `results/experiments/*.json`. Every document quotes this file.\n")
    a("## 1. Batch\n")
    a(f"- Title: {F.FULL_TITLE}\n- Product name in code: **SentinelFlow** (ports API {F.API_PORT}, web {F.WEB_PORT})\n- Students: " + "; ".join(f"{n} ({r})" for n, r in F.STUDENTS))
    a(f"- Guide: {F.GUIDE}\n- Base paper (3.BASE PAPER.docx): {F.BASE_PAPER}")
    a("- Also in the batch folder: arXiv 2605.26307 (carpet-bombing, RAG + LLM; 8.ProjectCode and archived_base_papers/) and arXiv 2502.00975 (reference paper). They are cited as related work.\n")
    a("## 2. What the shipped application displays (results/metrics.json)\n")
    s = F.SHIP
    a(f"- Model: {s['model']}, seed {s['random_seed']}, trained in {s['training_seconds']} s\n- Provenance: **{s['dataset_provenance']}** (`is_synthetic = {s['is_synthetic']}`)")
    a(f"- Rows: train {s['train_samples']:,}, test {s['test_samples']:,}; benign total {s['benign_total']:,}, attack total {s['attack_total']:,} (9,000 + 9,000 synthetic flows + 3,000 + 3,000 augmentation windows)")
    a(f"- Accuracy {s['accuracy'] * 100:.2f} %, precision {s['precision'] * 100:.2f} %, recall {s['recall'] * 100:.2f} %, F1 {s['f1'] * 100:.2f} %, ROC-AUC {s['roc_auc'] * 100:.2f} %")
    a(f"- Confusion matrix (benign, attack rows): {F.CMX}; false-positive rate {K['ship_fpr'] * 100:.3f} %")
    a("- Feature importance (shipped): " + ", ".join(f"{k} {v:.3f}" for k, v in sorted(F.IMP.items(), key=lambda t: -t[1])) + "\n")
    a("## 3. Real data: CICIDS2017 Friday-Afternoon-DDoS flows (scripts/run_experiments.py real)\n")
    a(f"- Source: Hugging Face mirror `c01dsnap/CIC-IDS2017` (MachineLearningCSV file `Friday-WorkingHours-Afternoon-DDos.pcap_ISCX.csv`, 77 MB; licence 'other', cite Sharafaldin et al. 2018). Not committed to the repository.")
    a(f"- Rows {R['rows']:,}: BENIGN {R['label_counts']['BENIGN']:,}, DDoS {R['label_counts']['DDoS']:,}. Mapped to the 10-feature schema with the product's own `ml/preprocessing.py`.\n")
    a(row("Experiment", "Accuracy", "Precision", "Recall", "F1", "FPR", "n"))
    a(row(*["---"] * 7))
    for name, d in [("Shipped (synthetic) model on all real flows", R["shipped_on_real_all"]), ("Shipped model on a 20 % stratified real sample", R["shipped_on_real_20pct"]),
                    ("RF retrained on real flows, seed 42, 20 % test", R["real_rf_seed42"]), ("RF retrained, block split (first 70 % train, last 30 % test)", R["real_rf_block_split"])]:
        a(row(name, *m(d), f"{d['n']:,}"))
    a(f"\n- Five-seed mean ± std (retrained RF, 20 % test): accuracy {F.mstd(*K['rr_acc'])} %, precision {F.mstd(*K['rr_prec'])} %, recall {F.mstd(*K['rr_rec'])} %, F1 {F.mstd(*K['rr_f1'])} %, FPR {F.mstd(*K['rr_fpr'], d=3)} % (seeds 42, 1, 2, 3, 4).")
    a(f"- Shipped model on real flows: ROC-AUC {K['shipreal_auc'] * 100:.1f} % (ranking is useful, the 0.5 threshold is not). Confusion: TN {R['shipped_on_real_all']['tn']:,}, FP {R['shipped_on_real_all']['fp']:,}, FN {R['shipped_on_real_all']['fn']:,}, TP {R['shipped_on_real_all']['tp']:,}.")
    a(f"- Retrained RF training time {R['real_rf_per_seed'][0]['train_seconds']} s, model file {R['real_rf_model_mb']} MB. Block-split test set is {R['block_split_test_benign_share'] * 100:.1f} % benign.\n")
    a("### Classifier comparison on the same real split (seed 42)\n")
    a(row("Classifier", "Accuracy", "F1", "FPR", "Train s", "Predict s (45,149 rows)"))
    a(row(*["---"] * 6))
    for n, d in R["baselines_seed42"].items():
        a(row(n, f"{d['accuracy'] * 100:.2f} %", f"{d['f1'] * 100:.2f} %", f"{d['fpr'] * 100:.2f} %", d["train_seconds"], d["predict_seconds_test_set"]))
    a("\n### Feature-group ablation (RF, real flows, seed 42)\n")
    a(row("Feature group", "Accuracy", "Recall", "FPR", "Features"))
    a(row(*["---"] * 5))
    for n, d in R["ablation_seed42"].items():
        a(row(n, f"{d['accuracy'] * 100:.2f} %", f"{d['recall'] * 100:.2f} %", f"{d['fpr'] * 100:.2f} %", len(d["features"])))
    a("\n- Importance of the retrained forest: " + ", ".join(f"{k} {v:.3f}" for k, v in sorted(R["real_rf_importance"].items(), key=lambda t: -t[1])) + "\n")
    a("### Real-trained flow model applied to simulator windows (flow-to-window scale gap)\n")
    for k, d in R["real_rf_on_sim_windows"].items():
        a(f"- {k}: accuracy {d['accuracy'] * 100:.1f} %, attack recall {d['recall'] * 100:.1f} %, ROC-AUC {d['roc_auc'] * 100:.1f} % (every window called benign)")
    a("\n## 4. Product training recipe on real flows (scripts/run_experiments.py hybrid)\n")
    a(f"- Real flows + 6,000 augmentation windows, capped at 120,000 rows ({H['benign']:,} benign / {H['attack']:,} attack), stratified 80/20, 200 trees.")
    a(f"- Mixed test set ({H['mixed_test']['n']:,} rows): accuracy {H['mixed_test']['accuracy'] * 100:.2f} %, F1 {H['mixed_test']['f1'] * 100:.2f} %, FPR {H['mixed_test']['fpr'] * 100:.3f} %.")
    a(f"- On all {R['rows']:,} real flows (about 80 % of the sampled ones seen in training): accuracy {H['hybrid_on_real_all_flows']['accuracy'] * 100:.2f} %.")
    for k, d in H["hybrid_on_sim_windows"].items():
        a(f"- Fresh simulator windows {k}: accuracy {d['accuracy'] * 100:.1f} %, FPR {d['fpr'] * 100:.1f} % (same generator that produced the augmentation rows - tautological).")
    a("\n## 5. Shipped model through the window pipeline (scripts/run_experiments.py windows)\n")
    a("4,000 windows per length from the product's own simulator generator (seed 2026, 35 % attack windows: 1,445 attack, 2,555 benign) aggregated by `traffic_aggregator`, stateful distributed risk (rolling 12-window baseline), persistence and severity as in `app.py`.\n")
    a(row("Window", "RF label alone: accuracy", "RF FPR", "High/Critical: accuracy", "High/Critical FPR", "High/Critical recall", "risk >= 0.7 alone: recall"))
    a(row(*["---"] * 7))
    for k in ("window_2s", "window_5s", "window_10s"):
        d = W[k]
        a(row(k[7:], f"{d['ml_only']['accuracy'] * 100:.1f} %", f"{d['ml_only']['fpr'] * 100:.1f} %", f"{d['actionable_high_or_critical']['accuracy'] * 100:.1f} %",
              f"{d['actionable_high_or_critical']['fpr'] * 100:.2f} %", f"{d['actionable_high_or_critical']['recall'] * 100:.1f} %", f"{d['distributed_risk_ge_0.7_only']['recall'] * 100:.1f} %"))
    a("\nPer traffic style at 5 s windows (share flagged by RF / reaching High or Critical; severity counts):\n")
    for st, d in W["window_5s"]["by_style"].items():
        a(f"- {st}: n={d['n']}, RF attack rate {d['ml_attack_rate'] * 100:.1f} %, actionable {d['actionable_rate'] * 100:.1f} %, mean packet rate {d['mean_packet_rate']:.0f}/s, severities {d['severity_counts']}")
    a("\nThe 10 s result (accuracy 100 % for the RF label) is measured on windows from the same generator that produced the training augmentation rows; it shows the model is calibrated to that generator, not that it detects real attacks.\n")
    a("## 6. Latency (scripts/run_experiments.py latency, 600 windows, host CPU at 100 % from other jobs)\n")
    a(f"- Mean {L['mean_packets_per_window']:.0f} packets per window (max {L['max_packets_per_window']}).")
    for k in ("aggregate_ms", "predict_ms", "risk_severity_ms", "mitigate_ms", "db_ms", "total_ms", "detect_to_mitigation_ms"):
        d = L[k]
        a(f"- {k}: median {d['p50']:.1f}, p95 {d['p95']:.1f}, max {d['max']:.0f} ms")
    a(f"- Single-window inference: as shipped (n_jobs={L['model_n_jobs_as_shipped']}) median {L['single_inference_ms_n_jobs_-1']['p50']:.0f} ms; with n_jobs=1 median {L['single_inference_ms_n_jobs_1']['p50']:.0f} ms.")
    a(f"- Model file {L['model_file_mb']} MB; load time {L['model_load_seconds']} s.")
    a("- Caveat: other sessions kept the CPU at 100 % during the measurement, so absolute numbers are upper bounds; relative costs are what matter. 'Detection to mitigation' is the time from the finished feature vector to the mitigation decision, as measured here; it is not wall-clock time since the first attack packet (a window must close first: 2-120 s, default 10 s).\n")
    a("## 7. REST API over HTTP on 127.0.0.1 (scripts/measure_api.py against a scratch copy, port 8915)\n")
    a(row("Endpoint", "Method", "Status", "p50 ms", "p95 ms", "max ms"))
    a(row(*["---"] * 6))
    for d in A["latency"]:
        a(row(d["path"], d["method"], d["status"], f"{d['p50_ms']:.1f}", f"{d['p95_ms']:.1f}", f"{d['max_ms']:.0f}"))
    a(f"\n- First detection after pressing Start (2 s windows): {A['first_detection_after_start_seconds']:.1f} s. During that run {A['live_sim_windows_scored']} windows were scored: {A['live_sim_by_prediction']}, severities {A['live_sim_by_severity']}, {A['live_sim_quarantines_recorded']} quarantine rows.")
    a(f"- Malformed-input probes: {A['probes_ok']}/{A['probes_total']} behaved as intended; backend healthy afterwards: {A['healthy_after_probes']}. Observed gap: `interface` accepts a 5,000-character string (no length check).")
    for p in A["probes"]:
        if "capture_error_after_6s" in p:
            a(f"- Live capture without Npcap: HTTP {p['status']} on start, then status.capture_error = '{p['capture_error_after_6s'][:140]}...' and mode = {p['mode_after_6s']}.")
    a("\n## 8. Tests\n")
    a(f"- `tests/` (pytest, scratch SQLite): {F.PYTEST_PASSED} of {F.PYTEST_TOTAL} pass (test_api 32, test_features_preprocessing 24, test_model_db 13, test_pipeline_modules 26); run 114 s on the loaded host. `docs/metrics/pytest.txt`.")
    a(f"- `scripts/smoke_test.py` against the live backend: {F.SMOKE_PASSED} of {F.SMOKE_TOTAL} checks pass; the three Vite-proxy checks were skipped because the dev server was not running. `docs/metrics/smoke_test.txt`.\n")
    a("## 9. Architecture\n")
    a("- Python 3.11 / Flask 3.1 / scikit-learn 1.9 (model pickled with 1.9.0, loaded with 1.9.1: warning only) / pandas / psutil / Scapy 2.8 / SQLite; React 19 + Vite 8 + Tailwind 4 + Recharts front end (about 3,100 lines of JSX/JS).")
    a("- Modules: `app.py` (389 lines), `ml/` (features, preprocessing, train_model, evaluate_model, model_loader), `monitoring/` (interface_manager, packet_capture, simulator, traffic_aggregator), `security/` (detector, distributed_analysis, severity, mitigation), `database/db.py`, `config/config.py`.")
    a("- Four SQLite tables: detections (14 columns), mitigations (6), health_samples (8), settings (2); no foreign keys.")
    a("- Defaults: window 10 s (2-120 allowed), baseline 12 windows, quarantine 40 s (x2 for Critical; 5-3600 allowed), health sample every 5 s, top 3 sources quarantined.")
    a("- Distributed risk = 0.30 min(src/30,1) + 0.30 min(dst/15,1) + 0.25 min(rate/1500,1) + 0.15 baseline-deviation; levels Low < 0.4 <= Medium < 0.7 <= High.")
    a("- Severity score: +30 Attack (or 8 x confidence if Benign), +15/+8 for confidence >= 0.9 / 0.75, +20/+12/+5 for rate >= 3000/1200/400, +20/+10 for risk >= 0.7/0.4, +8 for >= 25 sources or >= 12 destinations, +10/+5 for persistence >= 3 / 2; Benign capped at 45; Critical >= 70, High >= 50, Medium >= 28.")
    a("- 12 JSON endpoints: GET status, health, interfaces, detections, detections/latest, mitigations, settings, model/metrics; POST settings, monitor/start, monitor/stop, demo/start, demo/stop; plus `/` (legacy dashboard) and `/static/results/<file>`.")
    a("- Demo login of the React app is a browser-side gate (demo@sentinelflow.com / Demo@1234, localStorage); the REST API has no authentication and binds to 127.0.0.1.")
    a("- Hardware used: Intel Core i5-12500 (6 cores / 12 threads), 15.7 GB RAM, Windows 11 Pro, no GPU, no Npcap installed (live capture not possible on this machine).\n")
    a("## 10. Screenshot inventory (docs/screenshots, 1440x900, Simulation Mode data scored by the real model)\n")
    for f in sorted(os.listdir(F.SHOTS)):
        a(f"- {f}")
    a("\nOlder server-rendered dashboard captures live in `screenshots/` (8 files) and are used only in Appendix C.\n")
    a("## 11. Known limitations and defects found while documenting (state these plainly)\n")
    a("1. The shipped model was trained on synthetic fallback data (CICIDS2017 was unreachable when the product was built); 99.71 % accuracy is on a held-out split of that synthetic data plus simulator windows.")
    a(f"2. On real CICIDS2017 DDoS flows the shipped model scores {K['shipreal_acc'] * 100:.1f} % accuracy, {K['shipreal_rec'] * 100:.1f} % recall and {K['shipreal_fpr'] * 100:.1f} % false-positive rate.")
    a(f"3. Retrained on real flows with the same 10 features and hyper-parameters, the RF reaches {K['rr_acc'][0] * 100:.2f} % (5 seeds); the product's own training script would do this if the CSV were placed in data/raw/. The labels in CICIDS2017 are known to have flaws (Engelen et al.); random splits of flow data overlap in time.")
    a("4. Window length matters: the model was calibrated on 10 s windows; at 2 s and 5 s windows (the Simulation Mode default is 5 s, the screenshots were captured at 2 s) the RF label alone raises many false alarms; the severity layer removes most of them.")
    a("5. The landing page and Model page show the 99.71 % figure; the Model page carries a 'synthetic training data' warning, the landing page does not.")
    a("6. The OS firewall is never touched (`apply_os_firewall_block` is a stub returning applied: false): 'mitigation' is an application-level denylist inside SentinelFlow; no traffic is actually dropped.")
    a("7. Live capture needs Npcap and Administrator rights; it could not be tested end to end on this machine (the error path was tested).")
    a("8. The saved forest has n_jobs=-1, which makes single-window inference ~10x slower than n_jobs=1 for one row.")
    a("9. Not measured: real SDN deployment, throughput under real attack load, recovery time of a real service, carpet-bombing with real traffic (only the simulator's carpet style), multi-class detection, online learning.")
    a("10. `interface` setting is not length-validated; the REST API has no authentication (localhost-only by design).")
    return "\n".join(o) + "\n"


if __name__ == "__main__":
    path = os.path.join(F.DOCS, "REPORT_FACTS.md")
    open(path, "w", encoding="utf-8").write(build())
    print("wrote", path)
